"0.01" value="<?= e(number_format($e,2,'.','')) ?>" required></div><div class="form-group"><label>Water</label><input type="number" name="water_amount" min="0" step="0.01" value="<?= e(number_format($w,2,'.','')) ?>" required></div><div class="form-group"><label>Notes</label><textarea name="period_notes"><?= e($bp['notes']??'') ?></textarea></div><button class="btn btn-dark btn-sm">Save Billing</button></form></details><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
