type="hidden" name="id" value="<?= $id ?>"><div class="form-group admin-form-gap"><label>Refund Amount *</label><input type="number" name="refund_amount" min="0.01" max="<?= e(number_format($depositHeld,2,'.','')) ?>" step="0.01" value="<?= e(number_format($depositHeld,2,'.','')) ?>" required></div><div class="form-group admin-form-gap"><label>Refund Method *</label><select name="refund_method" data-booking-payment-method><?php foreach(booking_payment_methods() as $method): ?><option value="<?= e($method) ?>"><?= e(booking_payment_method_label($method)) ?></option><?php endforeach; ?></select></div><div class="form-group admin-form-gap"><label>Reference</label><input name="refund_reference" maxlength="120" data-booking-payment-reference data-allow-cash-reference></div><div class="form-group admin-form-gap"><label>Refunded At *</label><input type="datetime-local" name="refund_at" value="<?= e(date('Y-m-d\TH:i')) ?>" required></div><div class="form-group admin-form-gap"><label>Notes</label><textarea name="refund_notes"></textarea></div><button class="btn btn-dark btn-block">Record Refund</button></form></details><?php endif; ?><hr class="rental-action-divider"><?php endif; ?>
<div id="rental-payment"></div><?php if($rental['status']!=='cancelled'&&$balance>0.009): ?><h2><?= $paid>0.009?'Update Payment':'Record Payment' ?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_payment"><input type="hidden" name="id" value="<?= $id ?>"><div class="form-group admin-form-gap"><label>Amount *</label><input type="number" name="amount" min="0.01" max="<?= e(number_format($balance,2,'.','')) ?>" step="0.01" value="<?= e(number_format($balance,2,'.','')) ?>" required></div><div class="form-group admin-form-gap"><label>Payment Method *</label><select name="payment_method" data-booking-payment-method><?php foreach(booking_payment_methods() as $method): ?><option value="<?= e($method) ?>"><?= e(booking_payment_method_label($method)) ?></option><?php endforeach; ?></select></div><div class="form-group admin-form-gap"><label>Reference / OR</label><input name="payment_reference" maxlength="120" data-booking-payment-reference data-allow-cash-reference></div><div class="form-group admin-form-gap"><label>Paid At *</label><input type="datetime-local" name="paid_at" value="<?= e(date('Y-m-d\TH:i')) ?>" required></div><div class="form-group admin-form-gap"><label>Notes</label><textarea name="payment_notes"></textarea></div><button class="btn btn-primary btn-block"><?= $paid>0.009?'Update Payment':'Record Payment' ?></button></form><?php else: ?><div class="alert <?= $rental['status']==='cancelled'?'alert-warning':'alert-success' ?> rental-inline-alert"><?php if($rental['status']==='cancelled'&&$cancellation): ?>Cancellation settlement complete · Refunded <?= money((float)$cancellation['refund_amount']) ?> · TLH retained <?= money((float)$cancellation['retained_amount']) ?>.<?php else: ?><?= $isComplimentary&&$target<=0.009?'Complimentary rental — no payment due.':'Current total due is fully paid.' ?><?php endif; ?></div><?php endif; ?>
